import { createDebug } from '../../debug.js';
import { google } from 'googleapis';
import type {
  GoogleDocsHandlerConfig, GoogleDocsSheetItem,
} from '../../types/plugins/form-handlers/google-docs-handler.js';

export type {
  GoogleDocsHandlerConfig, GoogleDocsSheetItem,
} from '../../types/plugins/form-handlers/google-docs-handler.js';

const debug = createDebug('Uttori.Plugin.FormHandler.GoogleDocs');

/**
 * Converts a one-based column number to a Sheets column label, including columns after Z.
 * @param column One-based column number.
 * @returns Column label.
 */
const columnLabel = (column: number): string => {
  let label = '';
  while (column > 0) {
    column -= 1;
    label = String.fromCharCode(65 + (column % 26)) + label;
    column = Math.floor(column / 26);
  }
  return label;
};

/**
 * Google Docs/Sheets handler for form submissions.
 * @example <caption>GoogleDocsHandler</caption>
 * const googleDocsHandler = GoogleDocsHandler.create(config);
 */
class GoogleDocsHandler {
  /**
   * Creates a Google Docs handler with the provided configuration.
   * @param config Google Docs configuration.
   * @returns Form handler function.
   */
  static create(config: GoogleDocsHandlerConfig): import('../form-handler.js').FormHandlerFunction {
    if (!config.credentialsPath || !config.spreadsheetId || !config.sheetName) {
      throw new Error('Google Docs handler requires credentialsPath, spreadsheetId, and sheetName configuration');
    }

    /**
     * @param formData Form data.
     * @param formConfig Form configuration.
     * @param _req The request.
     * @param _res The response.
     * @returns Form handler result.
     */
    return async (formData: Record<string, unknown>, formConfig: import('../form-handler.js').FormConfig, _req: import('express').Request, _res: import('express').Response): Promise<import('../form-handler.js').FormHandlerResult> => {
      /* c8 ignore next 15 */
      try {
        debug('Writing to Google Sheets for form submission:', formConfig.name);

        await GoogleDocsHandler.appendRow(config, formData, formConfig);

        return {
          success: true,
        };
      } catch (error) {
        debug('Google Sheets writing failed:', error);
        return {
          success: false,
        };
      }
    };
  }

  /**
   * Appends a row to the Google Sheet.
   * @param config Handler configuration.
   * @param formData Form data.
   * @param formConfig Form configuration.
   * @returns The response from the Google Sheets API.
   */
  static async appendRow(config: GoogleDocsHandlerConfig, formData: Record<string, unknown>, formConfig: import('../form-handler.js').FormConfig): Promise<import('googleapis').sheets_v4.Schema$AppendValuesResponse> {
    debug('Appending row to Google Sheet:', config, formData, formConfig);

    // Load credentials
    const auth = new google.auth.GoogleAuth({
      keyFile: config.credentialsPath,
      scopes: [
        'https://www.googleapis.com/auth/spreadsheets',
      ],
    });

    const sheets = google.sheets({ version: 'v4', auth });

    // Prepare data row
    const rowData = GoogleDocsHandler.prepareRowData(formData, formConfig, config);

    // Append data to sheet
    const response = await sheets.spreadsheets.values.append({
      spreadsheetId: config.spreadsheetId,
      range: `${config.sheetName}!A:Z`,
      valueInputOption: 'RAW',
      insertDataOption: 'INSERT_ROWS',
      requestBody: {
        values: [rowData],
      },
    });

    debug('Data appended to Google Sheet successfully:', response.data);
    return response.data;
  }

  /**
   * Prepares row data for Google Sheets.
   * @param formData Form data.
   * @param formConfig Form configuration.
   * @param config Handler configuration.
   * @returns Row data array.
   */
  static prepareRowData(formData: Record<string, unknown>, formConfig: import('../form-handler.js').FormConfig, config: GoogleDocsHandlerConfig): string[] {

    const rowData: string[] = [];

    // Add timestamp if requested
    if (config.prependTimestamp) {
      rowData.push(new Date().toISOString());
    }

    // Add form name
    rowData.push(formConfig.name);

    // Use form field order
    for (const field of formConfig.fields) {
      // Preserve submitted 0 and false; only missing or null values become blank cells.
      rowData.push(String(formData[field.name] ?? ''));
    }

    return rowData;
  }

  /**
   * Creates a new Google Sheet with the specified name and sheet.
   * Not used in this handler but is useful for debugging.
   * @param config Handler configuration.
   * @param spreadsheetName Name for the new spreadsheet.
   * @param [headers] Custom headers for the spreadsheet (optional).
   * @returns The ID of the created spreadsheet.
   */
  static async createSpreadsheet(config: GoogleDocsHandlerConfig, spreadsheetName: string, headers?: string[]): Promise<string> {
    try {
      debug('Creating new Google Sheet:', spreadsheetName);

      const auth = new google.auth.GoogleAuth({
        keyFile: config.credentialsPath,
        scopes: [
          'https://www.googleapis.com/auth/spreadsheets',
          'https://www.googleapis.com/auth/drive',
        ],
      });

      const sheets = google.sheets({ version: 'v4', auth });

      // Create the spreadsheet
      const createResponse = await sheets.spreadsheets.create({
        requestBody: {
          properties: {
            title: spreadsheetName,
          },
          sheets: [
            {
              properties: {
                title: config.sheetName,
              },
            },
          ],
        },
      });

      const spreadsheetId = createResponse.data.spreadsheetId;
      if (!spreadsheetId) {
        throw new Error('Google Sheets did not return a spreadsheet ID');
      }
      debug('Created Google Sheet with ID:', spreadsheetId);

      // Set up headers if they exist
      if (headers && headers.length > 0) {

        const headerRow: string[] = [];

        // Add timestamp header if requested
        if (config.prependTimestamp) {
          headerRow.push('Timestamp');
        }

        // Add form name header
        headerRow.push('Form Name');

        // Match the field columns written by prepareRowData, in the caller's order.
        headerRow.push(...headers);

        // Write headers to sheet
        await sheets.spreadsheets.values.update({
          spreadsheetId,
          range: `${config.sheetName}!A1:${columnLabel(headerRow.length)}1`,
          valueInputOption: 'RAW',
          requestBody: {
            values: [headerRow],
          },
        });
      }

      return spreadsheetId;
    } catch (error) {
      debug('Failed to create Google Sheet:', error);
      throw new Error(`Failed to create Google Sheet: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  /**
   * Checks if a spreadsheet exists and is accessible.
   * Not used in this handler but is useful for debugging.
   * @param config Handler configuration.
   * @returns True if the spreadsheet exists and is accessible.
   */
  static async checkSpreadsheetExists(config: GoogleDocsHandlerConfig): Promise<boolean> {
    try {
      if (!config.spreadsheetId) {
        return false;
      }

      const auth = new google.auth.GoogleAuth({
        keyFile: config.credentialsPath,
        scopes: ['https://www.googleapis.com/auth/spreadsheets'],
      });

      const sheets = google.sheets({ version: 'v4', auth });

      // Try to get spreadsheet metadata
      await sheets.spreadsheets.get({
        spreadsheetId: config.spreadsheetId,
      });

      return true;
    } catch (error) {
      debug('Spreadsheet does not exist or is not accessible:', error instanceof Error ? error.message : String(error));
      return false;
    }
  }

  /**
   * Lists all spreadsheets the service account has access to.
   * Not used in this handler but is useful for debugging.
   * @param config Handler configuration.
   * @returns List of accessible spreadsheets.
   */
  static async listSpreadsheets(config: GoogleDocsHandlerConfig): Promise<GoogleDocsSheetItem[]> {
    const auth = new google.auth.GoogleAuth({
      keyFile: config.credentialsPath,
      scopes: [
        'https://www.googleapis.com/auth/spreadsheets',
        'https://www.googleapis.com/auth/drive',
      ],
    });

    // List all spreadsheets ("templates") the service account has access to and log them
    const drive = google.drive({ version: 'v3', auth });
    const filesRes = await drive.files.list({
      q: 'mimeType=\'application/vnd.google-apps.spreadsheet\'',
      fields: 'files(id, name)',
      pageSize: 100,
    });
    const templates = (filesRes.data.files || []).map((f) => ({ id: f.id, name: f.name }));
    debug('Accessible Google Sheets (templates):', templates);
    return templates;
  }
}

export default GoogleDocsHandler;
